U='org:ueno-bank';V='org:vinanzas';I='org:itti';GV='org:grupo-vazquez';RS='org:redisa';RP='org:redipro'
def leg(f,t,a,c,d,ins,refs,en,es): return dict(**{'from':f},to=t,amount=a,currency=c,date=d,instrument=ins,refs=refs,note_en=en,note_es=es)
def chain(id,ten,tes,sen,ses,legs,ren,res,loop,days):
    for i,l in enumerate(legs,1): l['step']=i
    legs=[dict(step=l['step'],**{k:v for k,v in l.items() if k!='step'}) for l in legs]
    return dict(id=id,title_en=ten,title_es=tes,summary_en=sen,summary_es=ses,legs=legs,reconciliation_en=ren,reconciliation_es=res,closes_loop=loop,elapsed_days=days)
